const BASE_URL = 'https://www.1map.co.za';
const EMAIL = 'hein@velocityfibre.co.za';
const PASSWORD = 'VeloF@2025';

let sessionCookie = null;

async function authenticate\(\) {
  // Step 1: GET login page for CSRF
  const loginPage = await fetch\(`${BASE_URL}/login`\);
  const html = await loginPage.text\(\);
  const csrfMatch = html.match\(/name="_csrf"\\s+value="\([^"]+\)"/\);
  const csrf = csrfMatch ? csrfMatch[1] : '';

  const setCookie = loginPage.headers.get\('set-cookie'\) || '';
  const cookies = setCookie.split\(','\).map\(c => \(c.split\(';'\)[0] || ''\).trim\(\)\).join\('; '\);

  // Step 2: POST login
  const resp = await fetch\(`${BASE_URL}/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Cookie: cookies },
    body: new URLSearchParams\({ _csrf: csrf, email: EMAIL, password: PASSWORD }\).toString\(\),
    redirect: 'manual',
  }\);

  const respCookies = resp.headers.get\('set-cookie'\) || '';
  const sidMatch = respCookies.match\(/connect\\.sid=\([^;]+\)/\);
  if \(!sidMatch\) throw new Error\('No session cookie'\);
  sessionCookie = sidMatch[1];

  // Step 3: Init layer
  await fetch\(`${BASE_URL}/app?layer=5121`, {
    headers: { Cookie: `connect.sid=${sessionCookie}` },
  }\);

  console.log\('Authenticated OK'\);
}

async function search\(query, layerId = '5121'\) {
  const formData = new URLSearchParams\({
    ungeocoded: 'false', left: '0', bottom: '0', right: '0', top: '0',
    selfilter: '', action: 'get', email: EMAIL, layerid: layerId,
    sort: 'prop_id', templateExpression: '', q: query,
    page: '1', start: '0', limit: '50',
  }\);

  const response = await fetch\(`${BASE_URL}/api/apps/app/getattributes`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
      Cookie: `connect.sid=${sessionCookie}`,
    },
    body: formData.toString\(\),
  }\);

  const text = await response.text\(\);
  try {
    return JSON.parse\(text\);
  } catch {
    return { success: false, result: [] };
  }
}

async function run\(\) {
  await authenticate\(\);

  const testDRs = [
    { dr: 'DR1730676', serial: 'ALCLB47CF963', zone: 'LAW' },
    { dr: 'DR1857413', serial: 'ALCLB480F517', zone: 'MOA' },
    { dr: 'DR469872', serial: 'ALCLB480FC46', zone: 'MAM' },
    { dr: 'DR1735307', serial: 'ALCLB48DBFD9', zone: 'LAW' },
    { dr: 'DR470546', serial: 'ALCLB4851707', zone: 'MAM' },
  ];

  // Try multiple layers
  const layers = ['5121', '5122', '5120', '5123', '5124', '5125', '5119', '5118'];

